import type { KeeprawFlyDocument } from "../../packages/schema/src/index";

export function scaleArchive(count: number, offset = 0): KeeprawFlyDocument {
  return {
    format: "keepraw-fly",
    formatVersion: "0.2.0",
    profile: { name: { native: "陈芳", romanized: "Fang Chen" } },
    frequentFlyerMemberships: [
      {
        id: "scale-membership",
        programId: "mileageplus",
        memberNumber: "123456789",
        associatedAirlines: ["UA"],
        defaultAirline: "UA",
        tier: "gold",
      },
    ],
    extensions: { "example.archive": { label: "档案", revision: 3 } },
    flights: Array.from({ length: count }, (_, index) => ({
      id: `scale-${index + offset}`,
      flightNumber: `UA${index + offset + 1}`,
      serviceDate: "2025-03-01",
      airline: { iata: "UA", icao: "UAL" },
      origin: { iata: "SFO" },
      destination: { iata: "LAX" },
      scheduledDeparture: "2025-03-01T10:00:00-08:00",
      scheduledArrival: "2025-03-01T11:30:00-08:00",
    })),
  };
}

